function publicTop(c,label,links){return '<nav class="public-nav"><div class="public-brand"><span class="brand-mark">'+ic(c,"car")+'</span>'+h(c,label)+'</div><div class="public-nav-links">'+links.map(function(x){return '<a href="#'+c.state.portal+'/'+encodeURIComponent(x)+'">'+h(c,x)+'</a>'}).join("")+'</div><div class="row-actions">'+action(c,"Switch portal","switcher")+action(c,c.state.portal==="marketing"?"Explore workspace":"My trips","go-workspace",null,"primary")+'</div></nav>'}
