function publicWrap(c,label,links,content){return '<div class="public-shell">'+publicTop(c,label,links)+'<main id="main-content">'+content+'</main><footer class="public-footer"><span>© Sage Auto 2026 · Interactive frontend reconstruction</span><span>Demo only · No live booking, billing or accounts</span></footer></div>'}
