if(p==="Features"||p==="Why Sage Auto")return publicWrap(c,"sageauto",["Home","Why Sage Auto","Features","Pricing","Get started"],'<section class="public-features"><span class="eyebrow">ONE CONNECTED BUSINESS SYSTEM</span><h1 style="margin:10px 0 23px">'+(p==="Features"?"Everything a car hire business needs":"Built around the entire rental lifecycle")+'</h1>'+featureCards+'</section>');
