if(kind==="extend"){rec=linkedBookings(c).find(function(b){return b.id===id});if(!rec)return "";title="Request a rental extension";desc=rec.id+" · "+rec.customer;body='<form id="p3c-form" class="form-grid">'+choice(c,"Additional days","days",["1","2","3","5","7"])+textarea(c,"Reason for extension","notes","Explain the extra time required")+'</form>'+notice(c,"Not automatically extended","The operator must check availability, price and agreement changes before accepting any request.");buttons=action(c,"Send extension request","submit:extend:"+id,null,"primary")}
